CATALOG = {'en':{row[0]:row[0] for row in ROWS}}
for index, language in enumerate(('hi','mr','ta','bn'), start=1):
    CATALOG[language] = {row[0]:row[index] for row in ROWS}


def translate(message, locale='en', **values):
    return CATALOG.get(locale, CATALOG['en']).get(message, message).format(**values)
